css:
html.morse-focus .notion-sidebar-container,
html.morse-focus .notion-help-button,
html.morse-focus .notion-page-controls {
  display: none !important;
}
html.morse-focus .notion-topbar {
  opacity: 0;
  transition: opacity .2s;
}
html.morse-focus .notion-topbar:hover {
  opacity: 1;
}
html.morse-focus .notion-page-content {
  max-width: 680px;
  margin-inline: auto;
}
.morse-focus-btn {
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
.morse-focus-btn:hover { background: rgba(55, 53, 47, .08); }

js:
const root = document.documentElement;
const btn = morse.el("button", { class: "morse-focus-btn", title: "Focus mode (Ctrl+Shift+.)" });
const set = on => {
  root.classList.toggle("morse-focus", on);
  btn.textContent = on ? "Exit focus" : "Focus";
  morse.store.set("on", on);
};
morse.on(btn, "click", () => set(!root.classList.contains("morse-focus")));
morse.on(document, "keydown", e => {
  if (e.key === "." && e.shiftKey && (e.ctrlKey || e.metaKey)) {
    e.preventDefault();
    set(!root.classList.contains("morse-focus"));
  }
});
morse.watch(".notion-topbar-action-buttons", bar => bar.prepend(btn));
set(morse.store.get("on", false));

return () => root.classList.remove("morse-focus");
